+  // test_predicate selects the mask reduction; cmpcode selects the outer eq/ne condition.
+  static void vectorTestCMove(C2_MacroAssembler* masm, int cmpcode, Register dst, Register src,
+                              VectorRegister mask, BasicType bt, uint vector_length, BoolTest::mask test_predicate) {
+    assert(test_predicate == BoolTest::ne || test_predicate == BoolTest::overflow, "unsupported predicate");
+    assert(cmpcode == BoolTest::eq || cmpcode == BoolTest::ne, "unsupported condition");
+    __ vsetvli_helper(bt, vector_length);
+    __ vcpop_m(t0, mask);
+    if (test_predicate == BoolTest::overflow) {
+      // Subtract vector_length so we can compare against zr without
+      // materializing vector_length in another register.
+      __ sub(t0, t0, vector_length);
+    }
+    __ enc_cmove(cmpcode, t0, zr, dst, src);
+  }
+
+  static void vectorTestCMove(C2_MacroAssembler* masm, int cmpcode, FloatRegister dst, FloatRegister src,
+                              VectorRegister mask, BasicType bt, uint vector_length,
+                              BoolTest::mask test_predicate, bool is_single) {
+    assert(test_predicate == BoolTest::ne || test_predicate == BoolTest::overflow, "unsupported predicate");
+    assert(cmpcode == BoolTest::eq || cmpcode == BoolTest::ne, "unsupported condition");
+    __ vsetvli_helper(bt, vector_length);
+    __ vcpop_m(t0, mask);
+    if (test_predicate == BoolTest::overflow) {
+      // Subtract vector_length so we can compare against zr without
+      // materializing vector_length in another register.
+      __ sub(t0, t0, vector_length);
+    }
+    __ enc_cmove_fp_cmp(cmpcode, t0, zr, dst, src, is_single);
+  }
