+// CMove with register values and a condition produced by VectorTest.
+//
+// The two rules above directly materialize a boolean (0 or 1) from anyTrue()/allTrue().
+// The rules below select between arbitrary register values, using the population
+// count to form the condition passed to the corresponding cmove encoder:
+//
+//   anytrue: vcpop.m t0, op1                  // t0 != 0 iff some element is set
+//   alltrue: vcpop.m t0, op1; sub t0, t0, vl  // t0 == 0 iff every element is set
+//
+// The outer Bool condition ($cop) is restricted to eq/ne by cmpOpEqNe.
+// Separate rules distinguish the VectorTest predicates: ne for anyTrue,
+// overflow for allTrue.
+
+instruct cmovI_vtest_anytrue(iRegINoSp dst, iRegI src, cmpOpEqNe cop, vRegMask op1, vRegMask op2) %{
+  predicate(static_cast<const VectorTestNode*>(n->in(1)->in(2))->get_predicate() == BoolTest::ne);
+  match(Set dst (CMoveI (Binary cop (VectorTest op1 op2)) (Binary dst src)));
+  format %{ "CMoveI $dst, (vectortest $cop $op1 $op2), $dst, $src\t#@cmovI_vtest_anytrue" %}
+  ins_encode %{
+    vectorTestCMove(masm, $cop$$cmpcode, $dst$$Register, $src$$Register,
+                    as_VectorRegister($op1$$reg), Matcher::vector_element_basic_type(this, $op1),
+                    Matcher::vector_length(this, $op1), BoolTest::ne);
+  %}
+  ins_pipe(pipe_slow);
+%}
+
+instruct cmovI_vtest_alltrue(iRegINoSp dst, iRegI src, cmpOpEqNe cop, vRegMask op1, vRegMask op2) %{
+  predicate(static_cast<const VectorTestNode*>(n->in(1)->in(2))->get_predicate() == BoolTest::overflow);
+  match(Set dst (CMoveI (Binary cop (VectorTest op1 op2)) (Binary dst src)));
+  format %{ "CMoveI $dst, (vectortest $cop $op1 $op2), $dst, $src\t#@cmovI_vtest_alltrue" %}
